// cols 把 "列名:类型" 展开成 []Column，让上面的表定义保持一行一张表。
func cols(specs ...string) []powersync.Column {
	out := make([]powersync.Column, 0, len(specs))
	for _, s := range specs {
		name, typ, ok := strings.Cut(s, ":")
		if !ok {
			panic("schema: 缺列类型: " + s)
		}
		out = append(out, powersync.Column{Name: name, Type: powersync.ColumnType(typ)})
	}
	return out
}
